const draft = $('Draft Item').first().json;
return $input.all().map(i => {
  const raw = JSON.stringify(i.json);
  let text = '';
  try { text = i.json.content?.parts?.map(p => p.text).join('') || i.json.text || i.json.output || ''; } catch (e) {}
  if (!text) text = raw;
  const m = text.replace(/```json|```/g,'').match(/\{[\s\S]*\}/);
  let qa = null; try { qa = m ? JSON.parse(m[0]) : null; } catch (e) {}
  return {json:{brand: draft.brand, title: draft.title, qa_ok: !!qa, verdict: qa?.verdict || 'UNPARSED', score: qa?.score ?? null, issues: qa?.issues || [], fixes: qa?.fixes || [], scripture_check: qa?.scripture_check || null, kjv_reference_text: qa?.kjv_reference_text || null, revised_caption: qa?.revised_caption || null, status_for_aria: qa?.verdict === 'PASS' ? 'NEEDS DANIEL' : 'QC', raw_preview: qa ? undefined : text.slice(0, 500)}};
});
